; Runtime linked into programs generated by Cerulia cc.
BITS 32
section .text.entry
global _start
extern cc_main, puts, putchar, printf, write, read, open, close, exit
_start:
    pop eax
    mov edx, esp
    push edx
    push eax
    call cc_main                 ; displacement at byte 6, patched by cc
    push eax
    call exit
    ud2
    times 32-($-$$) db 0
; Stable five-byte jump table; see tools/make_cc_runtime.py.
    jmp near puts
    jmp near putchar
    jmp near printf
    jmp near write
    jmp near read
    jmp near open
    jmp near close
    jmp near exit
